from datetime import date, timedelta


class Loyalty:
    def __init__(self) -> None:
        # customer -> list of (available_date, remaining_points)
        self._lots = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        points = int(amount // 10)
        if points > 0:
            self._lots.setdefault(customer, []).append(
                (day + timedelta(days=14), points)
            )
        return points

    def balance(self, customer: str, day: date) -> int:
        lots = self._lots.get(customer, [])
        return sum(
            pts for avail, pts in lots if avail <= day
        )

    def redeem(self, customer: str, points: int, day: date) -> None:
        if points % 100 != 0:
            raise ValueError("Points must be redeemed in multiples of 100")
        if points <= 0:
            raise ValueError("Redeem amount must be positive")
        if points > self.balance(customer, day):
            raise ValueError("Insufficient points")

        lots = self._lots.get(customer, [])
        remaining = points
        for i, (avail, pts) in enumerate(lots):
            if remaining == 0:
                break
            if avail <= day and pts > 0:
                take = min(pts, remaining)
                lots[i] = (avail, pts - take)
                remaining -= take
